import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FileService } from 'src/app/core/services/file.service';
import { FileTypeFilterPipe } from 'src/app/core/pipes';

@Component({
  selector: 'app-student-files',
  standalone: true,
  imports: [CommonModule,FileTypeFilterPipe],
  templateUrl: './student-files.component.html',
  styleUrls: ['./student-files.component.scss']
})
export class StudentFilesComponent implements OnInit {
  classId!: number;
  files: any[] = [];
  loading = true;

  constructor(private route: ActivatedRoute, private fileService: FileService) {}

  ngOnInit() {
    this.classId = +this.route.snapshot.params['id'];
    this.fileService.getFilesByClass(this.classId).subscribe({
      next: res => { this.files = res; this.loading = false; },
      error: err => { console.error('Erreur:', err); this.loading = false; }
    });
  }

  getTypeLabel(type: any): string {
    if (typeof type === 'number') {
      switch (type) {
        case 0: return 'Cours';
        case 1: return 'TD';
        case 2: return 'TP';
        default: return 'Autre';
      }
    }
    return type;
  }
}
<section class="container py-5">
  <h2 class="fw-bold text-center mb-4">
    <i class="bi bi-journal-text text-primary me-2"></i>
    Ressources de la classe
  </h2>

  <div *ngIf="loading" class="text-center my-5">
    <div class="spinner-border text-primary"></div>
  </div>

  <div *ngIf="!loading && files.length > 0">
    <div class="accordion" id="studentFilesAccordion">

      <div *ngFor="let type of ['Cours', 'TD', 'TP', 'Autre']">
        <div class="accordion-item mb-2" *ngIf="files | fileTypeFilter:type as group">
          <h2 class="accordion-header">
            <button class="accordion-button collapsed fw-bold" type="button"
                    data-bs-toggle="collapse"
                    [attr.data-bs-target]="'#s' + type.replace(' ','')">
              {{ type }} ({{ group.length }})
            </button>
          </h2>

          <div [id]="'s' + type.replace(' ','')" class="accordion-collapse collapse"
               data-bs-parent="#studentFilesAccordion">
            <div class="accordion-body">
              <div class="list-group">
                <a *ngFor="let f of group"
                   [href]="f.fileUrl" target="_blank"
                   class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                  <span>{{ f.title }}</span>
                  <i class="bi bi-download text-primary"></i>
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>

    </div>
  </div>

  <div *ngIf="!loading && !files.length" class="alert alert-info text-center mt-5">
    📭 Aucune ressource disponible pour cette classe.
  </div>
</section>
